  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`article_entity_id`),
  UNIQUE KEY `uq_article_entity_text` (`article_id`,`entity_id`,`entity_text`),
  KEY `idx_article_entity_article` (`article_id`),
  KEY `fk_article_entity_entity` (`entity_id`),
  CONSTRAINT `fk_article_entity_entity` FOREIGN KEY (`entity_id`) REFERENCES `entity` (`entity_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13263 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
