CREATE TABLE `sourceevidence` (
  `evidence_id` int NOT NULL AUTO_INCREMENT,
  `article_id` int DEFAULT NULL,
  `chunk_id` int DEFAULT NULL,
  `target_table` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
