  `confidence` float DEFAULT NULL,
  PRIMARY KEY (`evidence_id`),
  KEY `FK_Article_TO_SourceEvidence_1` (`article_id`),
  KEY `FK_ArticleChunk_TO_SourceEvidence_1` (`chunk_id`),
