  CONSTRAINT `FK_ArticleChunk_TO_SourceEvidence_1` FOREIGN KEY (`chunk_id`) REFERENCES `articlechunk` (`chunk_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3527 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
