INSERT INTO `sourceevidence` VALUES (1,1,1,'articlerelation',1,'지금까지 T1에 엄청난 충성도를 보였으며',0.8),(2,1,1,'articlerelation',2,'\'스매쉬\' 신금재와 이민형, 둘 중 어느 선수가 주전이 될지 쉽사리 예측하지 못했다',0.8),(3,1,1,'articlerelation',3,'T1 김정균 감독의 의자만 유독 뾰족한 가시가 돋친 것 같았다',0.9),(4,2,2,'articlerelation',4,'최인규 감독은',0.9),(5,2,2,'articlerelation',5,'한화생명 선수단',0.9),(6,2,2,'articlerelation',6,'올 초 열린 LCK컵에 이어',0.9),(7,2,2,'articlerelation',7,'신설 국제대회 퍼스트 스탠드 토너먼트까지 정상에 오르면서',0.9),(8,2,2,'articlerelation',8,'\'피넛\' 한왕호는 \"개인적으로 미드 시즌 인비테이셔널(MSI)에 나가고 싶다\"',0.9),(9,3,3,'articlerelation',9,'아시아 스타 챌린저스 인비테이셔널(ASCI)까지 정상에 올라',0.8),(10,3,3,'articlerelation',10,'지난 겨울 OK 저축은행 브리온 1군에 합류하는 기회를 얻었다.',0.8),(11,3,3,'articlerelation',11,'지난 겨울 OK 저축은행 브리온 1군에 합류하는 기회를 얻었다.',0.8),(12,3,3,'articlerelation',12,'LCK컵 그룹 대항전에서 1승4패를 거두는 데 그쳤다.',0.8),(13,3,3,'articlerelation',13,'최우범 감독도 두 신인 선수에 대한 기대감을 드러냈다.',0.8),(14,3,3,'articlerelation',14,'(함유진과 변정현은) LCK CL에서 잘하던 선수들이다.',0.8),(15,7,7,'articlerelation',15,'KT 롤스터와 T1의 맞대결로 막을 올린다.',0.9),(16,7,7,'articlerelation',16,'LCK CL은 LoL 챔피언스 코리아(LCK)와 마찬가지로 올해 총 5라운드 일정으로 정규 시즌을 진행한다.',0.8),(17,7,7,'articlerelation',17,'LCK가 MSI 선발전과 본 대회를 치르는 동안에는 휴식기를 가질 전망이다.',0.7),(18,4,4,NULL,NULL,'T1은 2025시즌에 \'구마유시\' 이민형과 \'스매쉬\' 신금재, 두 명의 선수가 주전 원거리 딜러 자리를 놓고 경쟁할 예정이다.',NULL),(19,4,4,NULL,NULL,'T1 김정균 감독은 지난 1월 LCK컵 초반 두 경기에 이민형을 내보냈다가 세 번째 경기부터 2군이던 신금재를 1군으로 콜업, 이후 잔여 경기에 전부 투입해 전략 변화를 꾀했다.',NULL),(20,4,4,NULL,NULL,'T1 조 마시 CEO가 이달 중순 SNS를 통해 선발 라인업 결정에 관여했음을 밝히면서 논란이 일었다.',NULL),(21,4,4,NULL,NULL,'김정균 감독은 지난 1월 LCK컵 초반 두 경기에 이민형을 내보냈다가 세 번째 경기부터 2군이던 신금재를 1군으로 콜업, 이후 잔여 경기에 전부 투입해 전략 변화를 꾀했다.',NULL),(22,4,4,NULL,NULL,'\'오너\' 문현준도 한 마디를 보탰다.',NULL),(23,5,5,NULL,NULL,'LCK 이정훈 사무총장이 2025시즌 개막을 앞두고',NULL),(24,5,5,NULL,NULL,'그는 \"2025년은 변화의 해\"라면서 \"LCK컵은 최초의 컵대회로 이색적인 그룹 대항전 방식을 선보였다.\"',NULL),(25,5,5,NULL,NULL,'2025 LCK 정규 시즌이 내달 2일 한화생명e스포츠과 젠지의 첫 대결로 대장정을 시작한다.',NULL),(26,5,5,NULL,NULL,'시즌 구조 변경 외에도 팀들의 수익성 강화를 위해 글로벌 매출 풀(Global Revenue Pool, GRP) 제도를 올해부터 시작한다.',NULL),(27,6,6,NU